"use client";
import { FormEvent, useEffect, useMemo, useState } from "react";
import "./dashboard.css";
import "./report.css";

const colaboradores = [
  ["Ana Manuel","EMP-001","Serviços Corporativos","Gestora Financeira","Ativo"],
  ["Mateus Costa","EMP-002","Operações","Responsável de Operações","Ativo"],
  ["Elisa Rocha","EMP-003","Pessoas e Cultura","Parceira de RH","Pendente"],
  ["David Kim","EMP-004","Serviços Corporativos","Analista de FP&A","Ativo"],
];
const modulos = ["Visão geral","Planeamento","Operações","Análises","Relatórios","Administração"];

export default function Home(){
 const [modulo,setModulo]=useState("Visão geral"),[pesquisa,setPesquisa]=useState(""),[painel,setPainel]=useState(false);
 const lista=useMemo(()=>colaboradores.filter(x=>x.join(" ").toLowerCase().includes(pesquisa.toLowerCase())),[pesquisa]);
 return <div className="site">
  <header className="topo">
   <div className="marca"><b>EP</b><span>Enterprise Performance</span></div>
   <nav aria-label="Navegação principal">{modulos.map(x=><button key={x} className={modulo===x?"selecionado":""} onClick={()=>setModulo(x)}>{x}</button>)}</nav>
   <div className="acoes"><button className="pesquisa-global">⌕ <span>Pesquisar</span><kbd>⌘K</kbd></button><button className="notificacao">◌<i/></button><button className="perfil"><b>PF</b><span>Pascoal Frederico<small>Administrador</small></span>⌄</button></div>
  </header>
  <div className="subnav"><div className="empresa"><span>DH</span><p><small>Empresa atual</small><b>Demo Holdings⌄</b></p></div><div className="atalhos"><button className="ativo">Resumo</button><button>Desempenho</button><button>Pessoas</button><button>Atividades</button></div><button className="ajuda">? Ajuda</button></div>
  <main>
   {modulo==="Administração"?<ConfiguracaoReal/>:modulo==="Planeamento"?<PerformanceControl/>:modulo==="Operações"?<PayrollFoundation/>:modulo==="Análises"?<WorkforceCost/>:modulo==="Relatórios"?<ManagementReport/>:modulo==="Visão geral"?<ExecutiveDashboard onNavigate={setModulo}/>:<>
   <section className="boas-vindas"><div><span className="etiqueta">SEGUNDA-FEIRA, 17 DE AGOSTO</span><h1>Boa tarde, Pascoal.</h1><p>Aqui está o que precisa da sua atenção e como a organização está a evoluir.</p></div><div className="botoes"><button className="secundario">↥ Exportar visão</button><button className="primario" onClick={()=>setPainel(true)}>＋ Criar atividade</button></div></section>
   <section className="filtros"><div><label>Período<select><option>Agosto 2026</option><option>Julho 2026</option></select></label><label>Cenário<select><option>Realizado</option><option>Orçamento</option><option>Previsão</option></select></label><label>Versão<select><option>Versão de trabalho 3</option></select></label><label>Moeda<select><option>Moeda de reporte</option></select></label></div><span>Atualizado há 2 minutos</span></section>
   <section className="resumo"><article className="destaque"><div><span>Resultado operacional</span><i>↗ 6,8%</i></div><strong>8,42 M USD</strong><p>540 mil USD acima do orçamento</p><div className="spark"><i/><i/><i/><i/><i/><i/><i/><i/></div></article><Metrica titulo="Custo da força de trabalho" valor="3,18 M USD" nota="2,4% acima do orçamento" cor="ambar"/><Metrica titulo="Colaboradores ativos" valor="148" nota="96,2% das posições ocupadas" cor="azul"/><Metrica titulo="Ações pendentes" valor="4" nota="2 requerem decisão hoje" cor="vermelho"/></section>
   <section className="grelha">
    <article className="cartao desempenho"><Cabecalho sobre="DESEMPENHO" titulo="Realizado versus orçamento" acao="Abrir análise"/><div className="legenda"><span><i className="real"/>Realizado</span><span><i className="orc"/>Orçamento</span><b>Mar — Ago 2026</b></div><div className="grafico"><div className="escala"><span>12 M</span><span>9 M</span><span>6 M</span><span>3 M</span><span>0</span></div><div className="plot"><i/><i/><i/><i/><svg viewBox="0 0 800 220" preserveAspectRatio="none"><path className="area" d="M0,183 C80,165 110,155 170,158 S270,118 330,130 S430,82 500,92 S600,45 680,58 S750,28 800,25 L800,220 L0,220Z"/><path className="linha-real" d="M0,183 C80,165 110,155 170,158 S270,118 330,130 S430,82 500,92 S600,45 680,58 S750,28 800,25"/><path className="linha-orc" d="M0,177 C100,165 150,146 210,148 S330,122 400,112 S520,90 600,82 S700,60 800,53"/></svg><div className="meses">{["Mar","Abr","Mai","Jun","Jul","Ago"].map(x=><span key={x}>{x}</span>)}</div></div></div><div className="explicacao"><i>✦</i><div><b>O que explica a evolução?</b><p>O resultado superou o plano em julho, impulsionado pelas receitas de serviços e menor despesa externa.</p></div><button>Ver causas →</button></div></article>
    <article className="cartao foco"><Cabecalho sobre="FOCO DO DIA" titulo="Prioridades para decisão" acao="Ver todas"/><Prioridade cor="vermelho" icone="!" titulo="Bloqueios na validação salarial" texto="3 colaboradores com dados de pagamento incompletos." etiqueta="Resolver hoje"/><Prioridade cor="ambar" icone="↗" titulo="Desvio de custos em Operações" texto="Horas extraordinárias 18,6% acima do plano." etiqueta="Impacto elevado"/><Prioridade cor="azul" icone="◷" titulo="Orçamento por aprovar" texto="Dois centros de custo aguardam revisão." etiqueta="Há 2 dias"/><footer><span>Impacto potencial</span><b>214 mil USD</b><p>Exposição estimada caso nenhuma ação seja tomada.</p></footer></article>
   </section>
   <section className="cartao equipa"><div className="cab-equipa"><Cabecalho sobre="ORGANIZAÇÃO E PESSOAS" titulo="Acompanhar a equipa" acao="Abrir módulo de Pessoas"/><div><label>⌕<input value={pesquisa} onChange={e=>setPesquisa(e.target.value)} placeholder="Pesquisar colaborador"/></label><button className="primario" onClick={()=>setPainel(true)}>＋ Novo colaborador</button></div></div><div className="lista">{lista.map(x=><article key={x[1]}><i>{x[0].split(" ").map(y=>y[0]).join("").slice(0,2)}</i><div><b>{x[0]}</b><span>{x[3]}</span></div><p>{x[2]}<small>{x[1]}</small></p><em className={x[4]==="Ativo"?"ok":"pendente"}>{x[4]}</em><button>•••</button></article>)}</div><footer><span>A mostrar {lista.length} de {colaboradores.length} colaboradores</span><button>Ver diretório completo →</button></footer></section>
   </>}
  </main>
  {painel&&<div className="overlay" onClick={()=>setPainel(false)}><aside className="painel" onClick={e=>e.stopPropagation()}><header><div><small>PESSOAS</small><h2>Novo colaborador</h2></div><button onClick={()=>setPainel(false)}>×</button></header><div className="form"><p>Registe os dados essenciais. Contrato e processamento salarial serão tratados nos respetivos fluxos.</p><label>Número do colaborador<input placeholder="EMP-005"/></label><div><label>Nome<input/></label><label>Apelido<input/></label></div><label>Unidade organizacional<select><option>Serviços Corporativos</option><option>Operações</option></select></label><label>Data de admissão<input type="date"/></label><aside><b>✓ Auditoria ativa</b><p>O utilizador, a data, o contexto e os dados submetidos serão registados.</p></aside></div><footer><button className="secundario" onClick={()=>setPainel(false)}>Cancelar</button><button className="primario" onClick={()=>setPainel(false)}>Criar colaborador</button></footer></aside></div>}
 </div>
}
function Metrica({titulo,valor,nota,cor}:{titulo:string;valor:string;nota:string;cor:string}){return <article className="metrica"><span>{titulo}</span><strong>{valor}</strong><p className={cor}>{nota}</p><div><i className={cor}/></div></article>}
function Cabecalho({sobre,titulo,acao}:{sobre:string;titulo:string;acao:string}){return <div className="cab"><div><span>{sobre}</span><h2>{titulo}</h2></div><button>{acao} →</button></div>}
function Prioridade({cor,icone,titulo,texto,etiqueta}:{cor:string;icone:string;titulo:string;texto:string;etiqueta:string}){return <div className="prioridade"><i className={cor}>{icone}</i><div><b>{titulo}</b><p>{texto}</p><span>{etiqueta}</span></div><button>Rever</button></div>}

type Organization={id:string;code:string;name:string;kind:string;currency:string;status:string};
type PlatformUser={id:string;name:string;email:string;role:string;organization_id?:string;status:string};
type Employee={id:string;employee_number:string;first_name:string;last_name:string;organization_id:string;job_title:string;hire_date:string;status:string};
type AuditEvent={id:string;summary:string;actor:string;created_at:string};
type FinancialDimension={id:string;code:string;name:string;description:string;status:string;member_count:number};
type DimensionMember={id:string;dimension_id:string;code:string;name:string;parent_id?:string;status:string};
type SetupData={organizations:Organization[];users:PlatformUser[];employees:Employee[];audit:AuditEvent[];dimensions:FinancialDimension[];dimensionMembers:DimensionMember[]};
const vazio:SetupData={organizations:[],users:[],employees:[],audit:[],dimensions:[],dimensionMembers:[]};
function ConfiguracaoReal(){
 const [etapa,setEtapa]=useState(1),[dados,setDados]=useState<SetupData>(vazio),[aberto,setAberto]=useState(false),[tipoModal,setTipoModal]=useState(""),[dimensaoAtiva,setDimensaoAtiva]=useState(""),[erro,setErro]=useState(""),[aEnviar,setAEnviar]=useState(false);
 const carregar=()=>fetch("/api/setup").then(async r=>{const d=await r.json();if(!r.ok||!Array.isArray(d.organizations))throw new Error(d.error);return d}).then(setDados).catch(()=>setErro("Não foi possível carregar os registos."));
 useEffect(()=>{carregar()},[]);
 async function submeter(e:FormEvent<HTMLFormElement>){e.preventDefault();setErro("");setAEnviar(true);const form=new FormData(e.currentTarget);const payload=Object.fromEntries(form.entries());payload.type=tipoModal||(etapa===1?"organization":etapa===2?"user":"employee");const res=await fetch("/api/setup",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const body=await res.json();setAEnviar(false);if(!res.ok){setErro(body.error||"Não foi possível guardar.");return}setDados(body);setAberto(false)}
 const total=dados.organizations.length+dados.users.length+dados.employees.length+dados.dimensions.length;
 return <section className="configuracao"><div className="config-top"><div><span>CONFIGURAÇÃO BASE</span><h1>Estrutura governada e auditável</h1><p>Crie a organização, atribua acessos e ligue cada colaborador ao seu âmbito.</p></div><b>{total} registos ativos</b></div><div className="progresso"><i style={{width:dados.organizations.length?dados.users.length?dados.employees.length?"100%":"67%":"34%":"8%"}}/></div>
 <div className="passos quatro">{[["1","Organização","Estrutura e moeda",dados.organizations.length?"Configurada":"Começar"],["2","Utilizadores","Funções e âmbito",`${dados.users.length} acessos`],["3","Colaboradores","Vínculos essenciais",`${dados.employees.length} registos`],["4","Dimensões financeiras","Eixos e hierarquias",`${dados.dimensions.length} dimensões`]].map((x,i)=><button key={x[1]} className={etapa===i+1?"passo ativo":"passo"} onClick={()=>{setEtapa(i+1);setAberto(false);setErro("")}}><i>{dados[["organizations","users","employees","dimensions"][i] as keyof SetupData].length?"✓":x[0]}</i><span><b>{x[1]}</b><small>{x[2]}</small></span><em>{x[3]}</em></button>)}</div>
 <div className="config-grid"><article className="cartao estrutura"><div className="cab"><div><span>{etapa===1?"ORGANIZAÇÃO":etapa===2?"UTILIZADORES":etapa===3?"COLABORADORES":"DIMENSÕES FINANCEIRAS"}</span><h2>{etapa===1?"Estrutura organizacional":etapa===2?"Acesso à plataforma":etapa===3?"Diretório essencial":"Eixos de análise configuráveis"}</h2></div><button onClick={()=>{setTipoModal(etapa===4?"dimension":"");setAberto(true)}}>＋ {etapa===1?"Nova unidade":etapa===2?"Convidar":etapa===3?"Novo colaborador":"Nova dimensão"}</button></div>
 {etapa===1?<div className="org-tree">{dados.organizations.length?dados.organizations.map(o=><div key={o.id}><i>{o.code.slice(0,2)}</i><span><b>{o.name}</b><small>{o.kind} · {o.currency}</small></span><em>{o.status}</em></div>):<Vazio texto="Ainda não existem unidades organizacionais."/>}</div>:etapa===2?<div className="user-list">{dados.users.length?dados.users.map(u=><div key={u.id}><i>{u.name.split(" ").map((n:string)=>n[0]).join("").slice(0,2)}</i><span><b>{u.name}</b><small>{u.role} · {u.email}</small></span><em>{u.status}</em></div>):<Vazio texto="Convide o primeiro utilizador."/>}</div>:etapa===3?<div className="user-list">{dados.employees.length?dados.employees.map(e=><div key={e.id}><i>{e.first_name[0]}{e.last_name[0]}</i><span><b>{e.first_name} {e.last_name}</b><small>{e.employee_number} · {e.job_title}</small></span><em>{e.status}</em></div>):<Vazio texto="Registe o primeiro colaborador."/>}</div>:<div className="dimensoes-lista">{dados.dimensions.length?dados.dimensions.map(d=><section key={d.id} className={dimensaoAtiva===d.id?"dimensao aberta":"dimensao"}><button onClick={()=>setDimensaoAtiva(dimensaoAtiva===d.id?"":d.id)}><i>{d.code.slice(0,2)}</i><span><b>{d.name}</b><small>{d.description}</small></span><em>{d.member_count} membros</em><strong>⌄</strong></button>{dimensaoAtiva===d.id&&<div className="membros">{dados.dimensionMembers.filter(m=>m.dimension_id===d.id).map(m=><div key={m.id} className={m.parent_id?"filho":""}><i>↳</i><span><b>{m.code}</b><small>{m.name}</small></span><em>{m.status}</em></div>)}<button onClick={()=>{setTipoModal("dimensionMember");setDimensaoAtiva(d.id);setAberto(true)}}>＋ Adicionar membro</button></div>}</section>):<Vazio texto="Crie a primeira dimensão de análise."/>}</div>}</article>
 <aside className="cartao controlos"><span>AUDITORIA RECENTE</span><h2>Alterações rastreáveis</h2>{dados.audit.length?dados.audit.map(a=><div key={a.id}><i>✓</i><span><b>{a.summary}</b><small>{a.actor} · {new Date(a.created_at).toLocaleString("pt-PT")}</small></span></div>):<p className="sem-auditoria">As primeiras alterações aparecerão aqui.</p>}<footer><b>Controlos ativos</b><p>Tenant, autor, data e entidade são registados em cada criação.</p></footer></aside></div>
 {aberto&&etapa===4&&<div className="modal-inline"><form onSubmit={submeter}><header><div><small>DIMENSÕES FINANCEIRAS</small><h2>{tipoModal==="dimensionMember"?"Novo membro":"Nova dimensão"}</h2></div><button type="button" onClick={()=>setAberto(false)}>×</button></header>{tipoModal==="dimensionMember"?<><input type="hidden" name="dimensionId" value={dimensaoAtiva}/><div><label>Código<input name="code" required autoFocus placeholder="EX.: OPS-01"/></label><label>Estado<select name="status"><option>Ativo</option></select></label></div><label>Nome do membro<input name="name" required/></label><label>Membro superior<select name="parentId"><option value="">Raiz da hierarquia</option>{dados.dimensionMembers.filter(m=>m.dimension_id===dimensaoAtiva).map(m=><option key={m.id} value={m.id}>{m.code} · {m.name}</option>)}</select></label></>:<><div><label>Código<input name="code" required autoFocus placeholder="EX.: CC"/></label><label>Estado<select name="status"><option>Ativa</option></select></label></div><label>Nome da dimensão<input name="name" required placeholder="Ex.: Centro de custo"/></label><label>Descrição<input name="description" required placeholder="Como esta dimensão será utilizada"/></label></>}{erro&&<p className="erro-form">{erro}</p>}<footer><button type="button" className="secundario" onClick={()=>setAberto(false)}>Cancelar</button><button className="primario" disabled={aEnviar}>{aEnviar?"A guardar…":"Guardar registo"}</button></footer></form></div>}
 {aberto&&etapa<4&&<div className="modal-inline"><form onSubmit={submeter}><header><div><small>NOVO REGISTO</small><h2>{etapa===1?"Unidade organizacional":etapa===2?"Convidar utilizador":"Novo colaborador"}</h2></div><button type="button" onClick={()=>setAberto(false)}>×</button></header>{etapa===1?<><label>Nome<input name="name" required autoFocus/></label><div><label>Código<input name="code" required placeholder="EX.: OPS"/></label><label>Moeda<input name="currency" required placeholder="ISO 4217" maxLength={3}/></label></div><label>Tipo<select name="kind"><option>Grupo</option><option>Empresa</option><option>Unidade</option><option>Departamento</option></select></label></>:etapa===2?<><label>Nome completo<input name="name" required autoFocus/></label><label>Email<input name="email" type="email" required/></label><div><label>Função<select name="role"><option>Gestor</option><option>Financeiro</option><option>Recursos Humanos</option><option>Leitura</option></select></label><label>Âmbito<select name="organizationId"><option value="">Todo o tenant</option>{dados.organizations.map(o=><option value={o.id} key={o.id}>{o.name}</option>)}</select></label></div></>:<><div><label>Número<input name="employeeNumber" required placeholder="EMP-001"/></label><label>Data de admissão<input name="hireDate" type="date" required/></label></div><div><label>Nome<input name="firstName" required/></label><label>Apelido<input name="lastName" required/></label></div><label>Unidade<select name="organizationId" required><option value="">Selecionar</option>{dados.organizations.map(o=><option value={o.id} key={o.id}>{o.name}</option>)}</select></label><label>Função<input name="jobTitle" required/></label></>}{erro&&<p className="erro-form">{erro}</p>}<footer><button type="button" className="secundario" onClick={()=>setAberto(false)}>Cancelar</button><button className="primario" disabled={aEnviar}>{aEnviar?"A guardar…":"Guardar registo"}</button></footer></form></div>}</section>
}
function Vazio({texto}:{texto:string}){return <div className="vazio-lista"><i>＋</i><b>{texto}</b><small>Use a ação acima para começar.</small></div>}

type BudgetVersion={id:string;name:string;fiscal_year:number;status:string};
type PerfEntry={id:string;period:string;scenario:string;currency:string;line_code:string;line_name:string;amount_minor:number;organization_name:string;dimension_member_name?:string;created_at:string};
type PerfData={period:string;currency:string;entries:PerfEntry[];versions:BudgetVersion[];organizations:{id:string;name:string;code:string;currency:string}[];members:{id:string;name:string;code:string;dimension_name:string}[];summary:{actualMinor:number;budgetMinor:number;varianceMinor:number;varianceBps:number|null};audit:AuditEvent[]};
const perfVazio:PerfData={period:"2026-08",currency:"AOA",entries:[],versions:[],organizations:[],members:[],summary:{actualMinor:0,budgetMinor:0,varianceMinor:0,varianceBps:null},audit:[]};
function PerformanceControl(){
 const [dados,setDados]=useState<PerfData>(perfVazio),[periodo,setPeriodo]=useState("2026-08"),[moeda,setMoeda]=useState("AOA"),[versao,setVersao]=useState(""),[modal,setModal]=useState(""),[erro,setErro]=useState(""),[aEnviar,setAEnviar]=useState(false);
 const carregar=()=>fetch(`/api/performance?period=${periodo}&currency=${moeda}&version=${versao}`).then(r=>r.json()).then(d=>{if(!Array.isArray(d.entries))throw new Error(d.error);setDados(d);if(!versao&&d.versions[0])setVersao(d.versions[0].id)}).catch(()=>setErro("Não foi possível carregar o controlo de performance."));
 useEffect(()=>{carregar()},[periodo,moeda,versao]);
 const dinheiro=(minor:number)=>new Intl.NumberFormat("pt-PT",{style:"currency",currency:moeda,maximumFractionDigits:2}).format(minor/100);
 async function enviar(e:FormEvent<HTMLFormElement>){e.preventDefault();setErro("");setAEnviar(true);const payload=Object.fromEntries(new FormData(e.currentTarget).entries());payload.type=modal;const res=await fetch(`/api/performance?period=${periodo}&currency=${moeda}&version=${versao}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const body=await res.json();setAEnviar(false);if(!res.ok){setErro(body.error||"Não foi possível guardar.");return}setDados(body);if(modal==="budgetVersion"&&body.versions[0])setVersao(body.versions[0].id);setModal("")}
 async function aprovar(id:string){setErro("");const res=await fetch(`/api/performance?period=${periodo}&currency=${moeda}&version=${versao}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({type:"approveBudget",versionId:id,period:periodo,currency:moeda})});const body=await res.json();if(!res.ok){setErro(body.error);return}setDados(body)}
 const vAtual=dados.versions.find(v=>v.id===versao);
 return <section className="performance"><div className="perf-top"><div><span>ACTUAL / BUDGET CONTROL</span><h1>Performance financeira governada</h1><p>Compare realizado e orçamento com valores determinísticos e rastreáveis.</p></div><div><button className="secundario" onClick={()=>setModal("budgetVersion")}>＋ Nova versão</button><button className="primario" onClick={()=>setModal("performanceEntry")}>＋ Novo valor</button></div></div>
 <section className="perf-filtros"><label>Período<input type="month" value={periodo} onChange={e=>setPeriodo(e.target.value)}/></label><label>Moeda<input value={moeda} maxLength={3} onChange={e=>setMoeda(e.target.value.toUpperCase())}/></label><label>Versão orçamental<select value={versao} onChange={e=>setVersao(e.target.value)}><option value="">Sem versão</option>{dados.versions.map(v=><option key={v.id} value={v.id}>{v.name} · {v.status}</option>)}</select></label><div><small>Estado</small><b className={vAtual?.status==="Aprovado"?"estado aprovado":"estado"}>{vAtual?.status||"Não configurado"}</b></div></section>
 <section className="perf-kpis"><article><span>Realizado</span><strong>{dinheiro(dados.summary.actualMinor)}</strong><small>{periodo}</small></article><article><span>Orçamento</span><strong>{dinheiro(dados.summary.budgetMinor)}</strong><small>{vAtual?.name||"Sem versão selecionada"}</small></article><article className={dados.summary.varianceMinor>0?"desvio-negativo":"desvio-positivo"}><span>Desvio absoluto</span><strong>{dinheiro(dados.summary.varianceMinor)}</strong><small>{dados.summary.varianceBps===null?"Sem base comparável":`${(dados.summary.varianceBps/100).toFixed(2)}% do orçamento`}</small></article></section>
 <div className="perf-grid"><article className="cartao perf-tabela"><div className="cab"><div><span>VALORES REGISTADOS</span><h2>Actual versus Budget</h2></div><em>{dados.entries.length} linhas</em></div>{dados.entries.length?<div className="tabela-wrap"><table><thead><tr><th>Linha</th><th>Organização</th><th>Dimensão</th><th>Cenário</th><th>Valor</th></tr></thead><tbody>{dados.entries.map(e=><tr key={e.id}><td><b>{e.line_code}</b><small>{e.line_name}</small></td><td>{e.organization_name}</td><td>{e.dimension_member_name||"Sem dimensão"}</td><td><em className={e.scenario==="Actual"?"actual":"budget"}>{e.scenario}</em></td><td><b>{dinheiro(e.amount_minor)}</b></td></tr>)}</tbody></table></div>:<Vazio texto="Registe o primeiro valor realizado ou orçamentado."/>}</article>
 <aside className="cartao perf-versoes"><span>WORKFLOW ORÇAMENTAL</span><h2>Versões e aprovação</h2>{dados.versions.length?dados.versions.map(v=><div key={v.id}><i>{v.status==="Aprovado"?"✓":"◷"}</i><span><b>{v.name}</b><small>{v.fiscal_year} · {v.status}</small></span>{v.status==="Rascunho"&&<button onClick={()=>aprovar(v.id)}>Aprovar</button>}</div>):<p className="sem-auditoria">Crie uma versão para iniciar o orçamento.</p>}<footer><b>Cálculo controlado</b><p>Os valores são guardados em unidades monetárias mínimas. O desvio é calculado como Realizado − Orçamento.</p><small>Último evento: {dados.audit[0]?.summary||"Nenhuma alteração registada"}</small></footer></aside></div>
 {erro&&<p className="erro-global">{erro}</p>}{modal&&<div className="modal-inline"><form onSubmit={enviar}><header><div><small>{modal==="budgetVersion"?"WORKFLOW ORÇAMENTAL":"REGISTO FINANCEIRO"}</small><h2>{modal==="budgetVersion"?"Nova versão orçamental":"Novo valor Actual / Budget"}</h2></div><button type="button" onClick={()=>setModal("")}>×</button></header>{modal==="budgetVersion"?<><label>Nome da versão<input name="name" required autoFocus placeholder="Ex.: Orçamento Base 2027"/></label><label>Ano fiscal<input name="fiscalYear" type="number" min="2000" max="2200" required defaultValue="2027"/></label></>:<><div><label>Organização<select name="organizationId" required><option value="">Selecionar</option>{dados.organizations.map(o=><option key={o.id} value={o.id}>{o.name}</option>)}</select></label><label>Período<input name="period" type="month" required defaultValue={periodo}/></label></div><div><label>Cenário<select name="scenario" required><option>Actual</option><option>Budget</option></select></label><label>Versão<select name="versionId" defaultValue={versao}><option value="">Não aplicável a Actual</option>{dados.versions.filter(v=>v.status==="Rascunho").map(v=><option key={v.id} value={v.id}>{v.name}</option>)}</select></label></div><div><label>Moeda<input name="currency" required maxLength={3} defaultValue={moeda}/></label><label>Valor<input name="amount" required inputMode="decimal" placeholder="0,00"/></label></div><div><label>Código da linha<input name="lineCode" required placeholder="EX.: REV-SERV"/></label><label>Descrição<input name="lineName" required placeholder="Receitas de serviços"/></label></div><label>Dimensão<select name="dimensionMemberId"><option value="">Sem dimensão</option>{dados.members.map(m=><option key={m.id} value={m.id}>{m.dimension_name} · {m.code} · {m.name}</option>)}</select></label></>}{erro&&<p className="erro-form">{erro}</p>}<footer><button type="button" className="secundario" onClick={()=>setModal("")}>Cancelar</button><button className="primario" disabled={aEnviar}>{aEnviar?"A guardar…":"Guardar"}</button></footer></form></div>}</section>
}

type PayrollData={profiles:Array<{id:string;employee_name:string;employee_number:string;currency:string;base_minor:number;periodicity:string;effective_from:string;status:string;dimension_member_name?:string}>;components:Array<{id:string;code:string;name:string;category:string;method:string;value_minor?:number;rate_bps?:number;employee_name?:string;status:string}>;runs:Array<{id:string;period:string;currency:string;status:string;employee_count:number;gross_minor:number;deduction_minor:number;employer_minor:number;net_minor:number}>;employees:Array<{id:string;employee_number:string;first_name:string;last_name:string}>;members:Array<{id:string;name:string;code:string;dimension_name:string}>;audit:AuditEvent[]};
const payrollVazio:PayrollData={profiles:[],components:[],runs:[],employees:[],members:[],audit:[]};
function PayrollFoundation(){
 const [dados,setDados]=useState<PayrollData>(payrollVazio),[vista,setVista]=useState("Perfis salariais"),[modal,setModal]=useState(""),[erro,setErro]=useState(""),[aEnviar,setAEnviar]=useState(false);
 const carregar=()=>fetch("/api/payroll").then(r=>r.json()).then(d=>{if(!Array.isArray(d.profiles))throw new Error(d.error);setDados(d)}).catch(()=>setErro("Não foi possível carregar a fundação de Payroll."));useEffect(()=>{carregar()},[]);
 const dinheiro=(minor:number,currency="AOA")=>new Intl.NumberFormat("pt-PT",{style:"currency",currency}).format(minor/100);
 async function enviar(e:FormEvent<HTMLFormElement>){e.preventDefault();setErro("");setAEnviar(true);const payload=Object.fromEntries(new FormData(e.currentTarget).entries());payload.type=modal;const res=await fetch("/api/payroll",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(payload)});const body=await res.json();setAEnviar(false);if(!res.ok){setErro(body.error||"Não foi possível executar a operação.");return}setDados(body);setModal("")}
 async function transitar(runId:string){setErro("");const res=await fetch("/api/payroll",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({type:"transitionPayrollRun",runId})});const body=await res.json();if(!res.ok){setErro(body.error);return}setDados(body)}
 const ultimo=dados.runs[0],acao=(status:string)=>status==="Rascunho"?"Validar":status==="Validado"?"Aprovar":status==="Aprovado"?"Fechar":"Fechado";
 return <section className="payroll"><div className="pay-top"><div><span>PAYROLL RUN FOUNDATION</span><h1>Processamento salarial controlado</h1><p>Configuração, cálculo e workflow sem regras laborais ou fiscais hardcoded.</p></div><div><button className="secundario" onClick={()=>setModal("salaryProfile")}>＋ Perfil salarial</button><button className="secundario" onClick={()=>setModal("payrollComponent")}>＋ Componente</button><button className="primario" onClick={()=>setModal("generatePayrollRun")}>▶ Processar</button></div></div>
 <div className="pay-alerta"><i>i</i><div><b>Core agnóstico a país</b><p>Este incremento não calcula impostos, contribuições ou regras laborais. Esses cálculos serão fornecidos por Country Packs versionados.</p></div></div>
 <section className="pay-resumo"><article><span>Perfis ativos</span><strong>{dados.profiles.filter(p=>p.status==="Ativo").length}</strong><small>de {dados.employees.length} colaboradores</small></article><article><span>Último processamento</span><strong>{ultimo?.period||"—"}</strong><small>{ultimo?.status||"Ainda não processado"}</small></article><article><span>Líquido calculado</span><strong>{ultimo?dinheiro(ultimo.net_minor,ultimo.currency):"—"}</strong><small>{ultimo?`${ultimo.employee_count} colaborador(es)`:"Sem resultados"}</small></article><article><span>Custo patronal</span><strong>{ultimo?dinheiro(ultimo.gross_minor+ultimo.employer_minor,ultimo.currency):"—"}</strong><small>Bruto + employer cost</small></article></section>
 <div className="pay-tabs">{["Perfis salariais","Componentes","Processamentos"].map(x=><button key={x} className={vista===x?"ativo":""} onClick={()=>setVista(x)}>{x}<em>{x==="Perfis salariais"?dados.profiles.length:x==="Componentes"?dados.components.length:dados.runs.length}</em></button>)}</div>
 <div className="pay-grid"><article className="cartao pay-lista"><div className="cab"><div><span>{vista.toUpperCase()}</span><h2>{vista==="Perfis salariais"?"Configuração por colaborador":vista==="Componentes"?"Componentes atribuídos":"Runs e workflow"}</h2></div></div>{vista==="Perfis salariais"?(dados.profiles.length?dados.profiles.map(p=><div className="pay-row" key={p.id}><i>{p.employee_name.split(" ").map(n=>n[0]).join("").slice(0,2)}</i><span><b>{p.employee_name}</b><small>{p.employee_number} · {p.periodicity} · desde {p.effective_from}</small></span><p>{dinheiro(p.base_minor,p.currency)}<small>{p.dimension_member_name||"Sem dimensão"}</small></p><em>{p.status}</em></div>):<Vazio texto="Crie o primeiro perfil salarial."/>):vista==="Componentes"?(dados.components.length?dados.components.map(c=><div className="pay-row componente" key={c.id}><i>{c.category==="Earning"?"＋":c.category==="Deduction"?"−":"◇"}</i><span><b>{c.code} · {c.name}</b><small>{c.employee_name||"Sem atribuição"} · {c.category}</small></span><p>{c.method==="Fixed"?dinheiro(c.value_minor||0):`${((c.rate_bps||0)/100).toFixed(2)}%`}<small>{c.method}</small></p><em>{c.status}</em></div>):<Vazio texto="Crie e atribua o primeiro componente."/>):(dados.runs.length?dados.runs.map(r=><div className="pay-run" key={r.id}><div><i>{r.status==="Fechado"?"✓":"◷"}</i><span><b>Payroll {r.period}</b><small>{r.employee_count} colaborador(es) · {r.currency}</small></span></div><div><span>Bruto<b>{dinheiro(r.gross_minor,r.currency)}</b></span><span>Deduções<b>{dinheiro(r.deduction_minor,r.currency)}</b></span><span>Líquido<b>{dinheiro(r.net_minor,r.currency)}</b></span></div><em className={`run-${r.status.toLowerCase()}`}>{r.status}</em>{r.status!=="Fechado"&&<button onClick={()=>transitar(r.id)}>{acao(r.status)} →</button>}</div>):<Vazio texto="Execute o primeiro Payroll Run."/>)}</article>
 <aside className="cartao pay-controlos"><span>CONTROLOS DO MOTOR</span><h2>Execução reproduzível</h2>{[["Montantes","Unidades mínimas"],["Percentagens","Basis points"],["Arredondamento","Determinístico"],["Evidência","Hash SHA-256"],["Segregação","Workflow explícito"]].map(x=><div key={x[0]}><i>✓</i><span><b>{x[0]}</b><small>{x[1]}</small></span></div>)}<footer><b>Última ação auditada</b><p>{dados.audit[0]?.summary||"Nenhuma ação de Payroll registada."}</p></footer></aside></div>
 {erro&&<p className="erro-global">{erro}</p>}{modal&&<div className="modal-inline"><form onSubmit={enviar}><header><div><small>PAYROLL FOUNDATION</small><h2>{modal==="salaryProfile"?"Novo perfil salarial":modal==="payrollComponent"?"Novo componente":"Executar Payroll Run"}</h2></div><button type="button" onClick={()=>setModal("")}>×</button></header>{modal==="salaryProfile"?<><label>Colaborador<select name="employeeId" required><option value="">Selecionar</option>{dados.employees.map(e=><option key={e.id} value={e.id}>{e.employee_number} · {e.first_name} {e.last_name}</option>)}</select></label><div><label>Salário base<input name="baseAmount" required inputMode="decimal" placeholder="0,00"/></label><label>Moeda<input name="currency" required maxLength={3} defaultValue="AOA"/></label></div><div><label>Periodicidade<select name="periodicity"><option>Mensal</option><option>Quinzenal</option><option>Semanal</option></select></label><label>Vigência<input name="effectiveFrom" type="date" required/></label></div><label>Dimensão financeira<select name="dimensionMemberId"><option value="">Sem dimensão</option>{dados.members.map(m=><option key={m.id} value={m.id}>{m.dimension_name} · {m.code} · {m.name}</option>)}</select></label></>:modal==="payrollComponent"?<><label>Atribuir ao colaborador<select name="employeeId" required><option value="">Selecionar</option>{dados.employees.map(e=><option key={e.id} value={e.id}>{e.employee_number} · {e.first_name} {e.last_name}</option>)}</select></label><div><label>Código<input name="code" required placeholder="EX.: ALIM"/></label><label>Ordem<input name="calculationOrder" type="number" defaultValue="100"/></label></div><label>Nome<input name="name" required placeholder="Subsídio de alimentação"/></label><div><label>Categoria<select name="category"><option value="Earning">Earning</option><option value="Deduction">Deduction</option><option value="EmployerCost">Employer Cost</option></select></label><label>Método<select name="method"><option value="Fixed">Valor fixo</option><option value="Percentage">Percentagem do base</option></select></label></div><label>Valor ou percentagem<input name="value" required inputMode="decimal" placeholder="Ex.: 25000,00 ou 3,00"/></label></>:<><div><label>Período<input name="period" type="month" required defaultValue="2026-08"/></label><label>Moeda<input name="currency" required maxLength={3} defaultValue="AOA"/></label></div><aside className="calculo-nota"><b>Resultado imutável</b><p>O run guardará os inputs, totais e hash de cálculo por colaborador.</p></aside></>}{erro&&<p className="erro-form">{erro}</p>}<footer><button type="button" className="secundario" onClick={()=>setModal("")}>Cancelar</button><button className="primario" disabled={aEnviar}>{aEnviar?"A processar…":modal==="generatePayrollRun"?"Calcular Payroll":"Guardar"}</button></footer></form></div>}</section>
}

type WorkforceData={period:string;currency:string;runs:Array<{id:string;period:string;currency:string;employee_count:number;net_minor:number;posting_count:number}>;postings:Array<{id:string;employee_name:string;employee_number:string;organization_name:string;dimension_member_name?:string;gross_minor:number;employer_minor:number;total_minor:number;source_hash:string}>;versions:BudgetVersion[];summary:{actualMinor:number;budgetMinor:number;varianceMinor:number;varianceBps:number|null};audit:AuditEvent[]};
const workforceVazio:WorkforceData={period:"2026-08",currency:"AOA",runs:[],postings:[],versions:[],summary:{actualMinor:0,budgetMinor:0,varianceMinor:0,varianceBps:null},audit:[]};
function WorkforceCost(){const [dados,setDados]=useState<WorkforceData>(workforceVazio),[periodo,setPeriodo]=useState("2026-08"),[moeda,setMoeda]=useState("AOA"),[versao,setVersao]=useState(""),[erro,setErro]=useState(""),[aEnviar,setAEnviar]=useState("");
 const carregar=()=>fetch(`/api/workforce?period=${periodo}&currency=${moeda}&version=${versao}`).then(r=>r.json()).then(d=>{if(!Array.isArray(d.postings))throw new Error(d.error);setDados(d);if(!versao&&d.versions[0])setVersao(d.versions[0].id)}).catch(()=>setErro("Não foi possível carregar Workforce Cost."));useEffect(()=>{carregar()},[periodo,moeda,versao]);const dinheiro=(n:number)=>new Intl.NumberFormat("pt-PT",{style:"currency",currency:moeda}).format(n/100);
 async function transferir(runId:string){setErro("");setAEnviar(runId);const res=await fetch(`/api/workforce?period=${periodo}&currency=${moeda}&version=${versao}`,{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({type:"postRun",runId,versionId:versao})});const body=await res.json();setAEnviar("");if(!res.ok){setErro(body.error);return}setDados(body);setPeriodo(body.period);setMoeda(body.currency)}
 return <section className="workforce"><div className="wf-top"><div><span>WORKFORCE COST BRIDGE</span><h1>Custos de pessoas ligados à performance</h1><p>Payroll fechado convertido em Actual financeiro por organização e dimensão.</p></div><b>HCM → Finance</b></div><section className="wf-filtros"><label>Período<input type="month" value={periodo} onChange={e=>setPeriodo(e.target.value)}/></label><label>Moeda<input value={moeda} maxLength={3} onChange={e=>setMoeda(e.target.value.toUpperCase())}/></label><label>Versão Budget<select value={versao} onChange={e=>setVersao(e.target.value)}><option value="">Sem versão</option>{dados.versions.map(v=><option key={v.id} value={v.id}>{v.name} · {v.status}</option>)}</select></label></section>
 <section className="wf-kpis"><article><span>Actual Workforce Cost</span><strong>{dinheiro(dados.summary.actualMinor)}</strong><small>Bruto + employer costs</small></article><article><span>Budget Workforce Cost</span><strong>{dinheiro(dados.summary.budgetMinor)}</strong><small>Linha financeira WORKFORCE</small></article><article className={dados.summary.varianceMinor>0?"desfavoravel":"favoravel"}><span>Desvio</span><strong>{dinheiro(dados.summary.varianceMinor)}</strong><small>{dados.summary.varianceBps===null?"Sem orçamento comparável":`${(dados.summary.varianceBps/100).toFixed(2)}% vs Budget`}</small></article><article><span>Colaboradores alocados</span><strong>{dados.postings.length}</strong><small>{dados.runs.filter(r=>Number(r.posting_count)>0).length} run(s) transferidos</small></article></section>
 <div className="wf-grid"><article className="cartao wf-tabela"><div className="cab"><div><span>ALOCAÇÃO DE CUSTOS</span><h2>Payroll → dimensões financeiras</h2></div><em>{dados.postings.length} linhas</em></div>{dados.postings.length?<div className="tabela-wrap"><table><thead><tr><th>Colaborador</th><th>Organização</th><th>Dimensão</th><th>Bruto</th><th>Employer cost</th><th>Total</th></tr></thead><tbody>{dados.postings.map(p=><tr key={p.id}><td><b>{p.employee_name}</b><small>{p.employee_number}</small></td><td>{p.organization_name}</td><td>{p.dimension_member_name||"Sem dimensão"}</td><td>{dinheiro(p.gross_minor)}</td><td>{dinheiro(p.employer_minor)}</td><td><b>{dinheiro(p.total_minor)}</b><small className="hash">#{p.source_hash.slice(0,8)}</small></td></tr>)}</tbody></table></div>:<Vazio texto="Transfira um Payroll Run fechado para gerar Workforce Cost."/>}</article><aside className="cartao wf-runs"><span>RUNS ELEGÍVEIS</span><h2>Transferência controlada</h2>{dados.runs.length?dados.runs.map(r=><div key={r.id}><i>{Number(r.posting_count)>0?"✓":"↗"}</i><span><b>Payroll {r.period}</b><small>{r.employee_count} colaborador(es) · {r.currency}</small></span>{Number(r.posting_count)>0?<em>Transferido</em>:<button disabled={aEnviar===r.id} onClick={()=>transferir(r.id)}>{aEnviar===r.id?"A transferir…":"Transferir"}</button>}</div>):<p className="sem-auditoria">Nenhum Payroll fechado disponível.</p>}<footer><b>Idempotência ativa</b><p>Cada Payroll Run só pode ser transferido uma vez. O hash original acompanha o custo.</p><small>{dados.audit[0]?.summary||"Nenhuma transferência auditada."}</small></footer></aside></div>{erro&&<p className="erro-global">{erro}</p>}</section>}

type DashData={versions:BudgetVersion[];summary:{actualMinor:number;budgetMinor:number;varianceMinor:number;varianceBps:number|null;workforceMinor:number;headcount:number};trend:Array<{period:string;actual_minor:number;budget_minor:number}>;drivers:Array<{line_code:string;line_name:string;actual_minor:number;budget_minor:number;variance_minor:number}>;entries:Array<PerfEntry&{source:string}>;coverage:{organizations:number;sources:number;latestAt:string|null};payroll:{period:string;status:string}|null};
const dashEmpty:DashData={versions:[],summary:{actualMinor:0,budgetMinor:0,varianceMinor:0,varianceBps:null,workforceMinor:0,headcount:0},trend:[],drivers:[],entries:[],coverage:{organizations:0,sources:0,latestAt:null},payroll:null};
function ExecutiveDashboard({onNavigate}:{onNavigate:(module:string)=>void}){const [d,setD]=useState<DashData>(dashEmpty),[period,setPeriod]=useState("2026-08"),[currency,setCurrency]=useState("AOA"),[version,setVersion]=useState(""),[driver,setDriver]=useState("");useEffect(()=>{fetch(`/api/dashboard?period=${period}&currency=${currency}&version=${version}`).then(r=>r.json()).then(x=>{setD(x);if(!version&&x.versions?.[0])setVersion(x.versions[0].id)})},[period,currency,version]);const money=(n:number)=>new Intl.NumberFormat("pt-PT",{style:"currency",currency}).format(n/100),max=Math.max(1,...d.trend.flatMap(x=>[Number(x.actual_minor),Number(x.budget_minor)])),cause=d.drivers.slice().sort((a,b)=>Math.abs(b.variance_minor)-Math.abs(a.variance_minor))[0];return <section className="executivo"><div className="exec-top"><div><span>PERFORMANCE EXECUTIVA</span><h1>Decidir com contexto, não só com números</h1><p>Actual e Budget consolidados a partir dos motores Finance e HCM.</p></div><button className="primario" onClick={()=>onNavigate("Planeamento")}>Abrir planeamento →</button></div><section className="exec-filtros"><label>Período<input type="month" value={period} onChange={e=>setPeriod(e.target.value)}/></label><label>Comparação<select disabled><option>Actual vs Budget</option></select></label><label>Versão<select value={version} onChange={e=>setVersion(e.target.value)}><option value="">Sem versão</option>{d.versions.map(v=><option key={v.id} value={v.id}>{v.name} · {v.status}</option>)}</select></label><label>Moeda<input value={currency} maxLength={3} onChange={e=>setCurrency(e.target.value.toUpperCase())}/></label><small>{d.coverage.latestAt?`Atualizado ${new Date(d.coverage.latestAt).toLocaleString("pt-PT")}`:"Sem lançamentos"}</small></section><section className="exec-kpis"><article><span>Actual consolidado</span><strong>{money(d.summary.actualMinor)}</strong><small>{d.coverage.organizations} organização(ões) · {d.coverage.sources} fonte(s)</small></article><article><span>Budget selecionado</span><strong>{money(d.summary.budgetMinor)}</strong><small>{d.versions.find(v=>v.id===version)?.name||"Sem versão"}</small></article><article className={d.summary.varianceMinor>0?"desfavoravel":"favoravel"}><span>Desvio Actual − Budget</span><strong>{money(d.summary.varianceMinor)}</strong><small>{d.summary.varianceBps===null?"Sem base comparável":`${(d.summary.varianceBps/100).toFixed(2)}% vs Budget`}</small></article><article><span>Workforce Cost</span><strong>{money(d.summary.workforceMinor)}</strong><small>{d.summary.headcount} colaborador(es) ativos</small></article></section><div className="exec-grid"><article className="cartao exec-trend"><div className="cab"><div><span>TENDÊNCIA</span><h2>Actual versus Budget</h2></div><em>6 períodos</em></div><div className="exec-bars">{d.trend.map(x=><div key={x.period}><span><i className="actual" style={{height:`${Math.max(3,Number(x.actual_minor)/max*100)}%`}}/><i className="budget" style={{height:`${Math.max(3,Number(x.budget_minor)/max*100)}%`}}/></span><small>{x.period}</small></div>)}</div><footer><b>● Actual</b><b>● Budget</b></footer></article><aside className="cartao exec-explain"><span>EXPLICAÇÃO DETERMINÍSTICA</span><h2>{cause?`${cause.line_name} é o maior driver do desvio`:"Sem causa calculável"}</h2><p>{cause?`Impacto de ${money(cause.variance_minor)}, calculado diretamente dos lançamentos do período.`:"Registe Actual e Budget comparáveis para identificar causas."}</p><div><b>Contexto</b><small>{period} · {currency} · Actual vs Budget</small></div><div><b>Perspetiva</b><small>{d.payroll?`Payroll ${d.payroll.period} ${d.payroll.status}`:"Sem Payroll no contexto"}</small></div><button onClick={()=>onNavigate(cause?.line_code==="WORKFORCE"?"Análises":"Planeamento")}>Investigar origem →</button></aside></div><article className="cartao exec-drill"><div className="cab"><div><span>DRILL-DOWN</span><h2>Linhas que explicam o resultado</h2></div>{driver&&<button onClick={()=>setDriver("")}>Limpar seleção</button>}</div><div className="tabela-wrap"><table><thead><tr><th>Linha</th><th>Actual</th><th>Budget</th><th>Desvio</th><th></th></tr></thead><tbody>{d.drivers.map(x=><tr key={x.line_code}><td><b>{x.line_name}</b><small>{x.line_code}</small></td><td>{money(x.actual_minor)}</td><td>{money(x.budget_minor)}</td><td>{money(x.variance_minor)}</td><td><button onClick={()=>setDriver(x.line_code)}>Ver origem →</button></td></tr>)}</tbody></table></div>{driver&&<div className="drill-through"><b>Drill-through · {driver}</b>{d.entries.filter(x=>x.line_code===driver).map(x=><div key={x.id}><span>{x.organization_name}<small>{x.dimension_member_name||"Sem dimensão"} · {x.source}</small></span><em>{x.scenario}</em><strong>{money(x.amount_minor)}</strong></div>)}</div>}</article></section>}

type ReportItem={id:string;report_number:number;title:string;template:string;period:string;currency:string;status:string;input_hash:string;created_by:string;created_at:string;payload?:ReportPayload};type ReportPayload={generatedAt:string;parameters:{period:string;currency:string;versionName:string;template:string};result:{actualMinor:number;budgetMinor:number;varianceMinor:number;varianceBps:number|null;workforceMinor:number};cause:{lineCode:string;lineName:string;varianceMinor:number}|null;impact:string;perspective:string;recommendation:string;drivers:Array<{lineCode:string;lineName:string;actualMinor:number;budgetMinor:number;varianceMinor:number}>};
function ManagementReport(){const [items,setItems]=useState<ReportItem[]>([]),[versions,setVersions]=useState<BudgetVersion[]>([]),[report,setReport]=useState<ReportItem|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState("");const load=()=>fetch("/api/management-reports").then(r=>r.json()).then(x=>{setItems(x.reports||[]);setVersions(x.versions||[])});useEffect(()=>{load()},[]);async function generate(e:FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setError("");const res=await fetch("/api/management-reports",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget).entries()))}),body=await res.json();setBusy(false);if(!res.ok){setError(body.error);return}setReport(body);load()}async function open(id:string){const x=await fetch(`/api/management-reports?id=${id}`).then(r=>r.json());setReport(x)}const money=(n:number,c:string)=>new Intl.NumberFormat("pt-PT",{style:"currency",currency:c}).format(n/100),p=report?.payload;return <section className="reports"><div className="reports-top"><div><span>MANAGEMENT REPORTING</span><h1>Da performance à recomendação executiva</h1><p>Versões imutáveis, parâmetros explícitos e narrativa suportada pelos motores.</p></div>{report&&<button className="primario" onClick={()=>window.print()}>↥ Exportar / Imprimir</button>}</div><div className="reports-layout"><aside className="report-builder"><span>NOVO RELATÓRIO</span><h2>Parâmetros da versão</h2><form onSubmit={generate}><label>Título<input name="title" defaultValue="Relatório Mensal de Performance" required/></label><label>Template<select name="template"><option>Executivo</option><option>Controller</option><option>Board Pack</option></select></label><div><label>Período<input name="period" type="month" defaultValue="2026-08" required/></label><label>Moeda<input name="currency" defaultValue="AOA" maxLength={3} required/></label></div><label>Versão Budget<select name="versionId"><option value="">Sem versão</option>{versions.map(v=><option key={v.id} value={v.id}>{v.name} · {v.status}</option>)}</select></label>{error&&<p className="erro-form">{error}</p>}<button className="primario" disabled={busy}>{busy?"A gerar…":"Gerar versão auditável"}</button></form><div className="report-history"><b>VERSÕES EMITIDAS</b>{items.map(x=><button key={x.id} onClick={()=>open(x.id)} className={report?.id===x.id?"active":""}><span>v{x.report_number} · {x.title}<small>{x.period} · {x.currency}</small></span><em>{x.status}</em></button>)}</div></aside><article className="report-paper">{p&&report?<><header><div><span>EP</span><p><b>Enterprise Performance</b><small>Management Report · v{report.report_number}</small></p></div><em>{report.status}</em></header><section className="report-title"><small>{p.parameters.template.toUpperCase()} · {p.parameters.period} · {p.parameters.currency}</small><h2>{report.title}</h2><p>Actual versus {p.parameters.versionName}</p></section><div className="report-sections"><ReportSection number="01" title="Resultado"><strong>{money(p.result.actualMinor,report.currency)}</strong><p>Resultado Actual consolidado no período selecionado.</p></ReportSection><ReportSection number="02" title="Comparação"><strong>{money(p.result.varianceMinor,report.currency)}</strong><p>{p.result.varianceBps===null?"Não existe Budget comparável.":`${(p.result.varianceBps/100).toFixed(2)}% face ao Budget de ${money(p.result.budgetMinor,report.currency)}.`}</p></ReportSection><ReportSection number="03" title="Causa"><strong>{p.cause?.lineName||"Sem causa calculável"}</strong><p>{p.cause?`Maior contribuição para o desvio: ${money(p.cause.varianceMinor,report.currency)}.`:"Não existem linhas comparáveis."}</p></ReportSection><ReportSection number="04" title="Impacto"><p>{p.impact}</p><small>Workforce Cost: {money(p.result.workforceMinor,report.currency)}</small></ReportSection><ReportSection number="05" title="Perspetiva"><p>{p.perspective}</p></ReportSection><ReportSection number="06" title="Recomendação"><p>{p.recommendation}</p></ReportSection></div><section className="report-table"><h3>Anexo · Drivers por linha</h3><table><thead><tr><th>Linha</th><th>Actual</th><th>Budget</th><th>Desvio</th></tr></thead><tbody>{p.drivers.map(x=><tr key={x.lineCode}><td><b>{x.lineName}</b><small>{x.lineCode}</small></td><td>{money(x.actualMinor,report.currency)}</td><td>{money(x.budgetMinor,report.currency)}</td><td>{money(x.varianceMinor,report.currency)}</td></tr>)}</tbody></table></section><footer><span>Hash de inputs: {report.input_hash}</span><span>Emitido em {new Date(report.created_at).toLocaleString("pt-PT")}</span></footer></>:<div className="report-empty"><i>▤</i><h2>Pré-visualização do relatório</h2><p>Gere uma versão ou selecione um relatório emitido.</p></div>}</article></div></section>}
function ReportSection({number,title,children}:{number:string;title:string;children:React.ReactNode}){return <section><header><i>{number}</i><h3>{title}</h3></header><div>{children}</div></section>}
